Step 1: Create the Zod schema
Create:
src/features/auth/register.schema.ts
import { z } from "zod";
export const registerSchema =
  z
    .object({
      username:
        z
          .string()
          .trim()
          .min(
            1,
            "Username is required."
          )
          .min(
            3,
            "Username must contain at least 3 characters."
          )
          .max(
            20,
            "Username cannot exceed 20 characters."
          )
          .regex(
            /^[A-Za-z0-9_]+$/,
            "Use only letters, numbers, and underscores."
          ),
      displayName:
        z
          .string()
          .trim()
          .min(
            1,
            "Display name is required."
          )
          .min(
            2,
            "Display name must contain at least 2 characters."
          )
          .max(
            50,
            "Display name cannot exceed 50 characters."
          ),
      email:
        z
          .string()
          .trim()
          .min(
            1,
            "Email is required."
          )
          .email(
            "Enter a valid email address."
          )
          .transform(
            (email) =>
              email.toLowerCase()
          ),
      password:
        z
          .string()
          .min(
            1,
            "Password is required."
          )
          .min(
            8,
            "Password must contain at least 8 characters."
          )
          .max(
            72,
            "Password cannot exceed 72 characters."
          )
          .regex(
            /[A-Z]/,
            "Password must contain an uppercase letter."
          )
          .regex(
            /[a-z]/,
            "Password must contain a lowercase letter."
          )
          .regex(
            /[0-9]/,
            "Password must contain a number."
          ),
      confirmPassword:
        z
          .string()
          .min(
            1,
            "Confirm your password."
          ),
      acceptTerms:
        z
          .boolean()
          .refine(
            (accepted) =>
              accepted,
            {
              message:
                "You must accept the terms.",
            }
          ),
    })
    .refine(
      (values) =>
        values.password ===
        values.confirmPassword,
      {
        path: [
          "confirmPassword",
        ],
        message:
          "Passwords do not match.",
      }
    );
export type RegisterInput =
  z.input<
    typeof registerSchema
  >;
export type RegisterOutput =
  z.output<
    typeof registerSchema
  >;


  Why use z.object()?
z.object({
  username: z.string(),
  email: z.string(),
});
z.object() describes the expected shape of the complete form.
Registration object
├── username: string
├── displayName: string
├── email: string
├── password: string
├── confirmPassword: string
└── acceptTerms: boolean
If a field has the wrong runtime type, the schema rejects it.


  Why use refine()?
Field-level methods validate one field.
z.string().min(8)
Password confirmation depends on two fields:
values.password ===
values.confirmPassword
That is a cross-field rule.
.refine(
  (values) =>
    values.password ===
    values.confirmPassword,
  {
    path: [
      "confirmPassword",
    ],
    message:
      "Passwords do not match.",
  }
)
The path is essential.
Without it, the issue may belong to the complete object.
With:
path: [
  "confirmPassword",
]
the error is associated with:
errors.confirmPassword
