  //     },
  //     body: JSON.stringify(input),
  //   }
  // );
  await new Promise(
    (resolve) => {
      setTimeout(resolve, 1000);
    }
  );
  if (
    input.email ===
    "existing@example.com"
  ) {
    throw new ApiError(
      409,
      {
        success: false,
        field: "email",
        message:
          "An account with this email already exists.",
      }
    );
  }
  if (
    input.username
      .toLowerCase() ===
    "admin"
  ) {
    throw new ApiError(
      409,
      {
        success: false,
        field: "username",
        message:
          "This username is not available.",
      }
    );
  }
  return {
    success: true,
    message:
      "Registration successful. Check your email to verify your account.",
    data: {
      user: {
        id:
          crypto.randomUUID(),
        username:
          input.username,
        displayName:
          input.displayName,
        email:
          input.email,
      },
    },
  };
}
